"""Seal audited evidence after human-visible visual inspection; no simulations."""
from common import *
from finalize import csvread
import datetime

def main():
    utc=datetime.datetime.now(datetime.timezone.utc).isoformat()
    q=read(OUT/'checks/quality_checks.json');assert q['passed'] and q['independent_audit_passed']
    completion=read(OUT/'checks/reporting_completion.json');assert all(m['returncode']==0 for m in completion['modules'])
    required='''provenance/freeze_manifest.json provenance/physical_registry.csv provenance/cache_reuse_manifest.json grids/g0.json grids/g1.json grids/refinement_history.jsonl status/point_status.csv metrics/request_pairs.csv metrics/request_accuracy.csv metrics/judgments.csv metrics/judgment_summary.csv capacity/capacities.csv capacity/sequences.jsonl decisions/ranking.csv decisions/operating_points.csv applicability/evidence_cells.csv applicability/load_bands.csv runtime/environment.json runtime/evaluator_samples.csv runtime/reference_execution.csv runtime/cache_processing.csv runtime/matched_ratios.csv runtime/planning_cost.json checks/quality_checks.json checks/budget_ledger.json checks/stop_summary.json reports/FINAL_EVIDENCE_REPORT.md'''.split()
    assert all((OUT/p).is_file() and (OUT/p).stat().st_size>0 for p in required)
    assert len(list((OUT/'evaluator').glob('*.json.gz')))==2850
    assert len(list((OUT/'reference').glob('*.json.gz')))==300
    figs=sorted((OUT/'figures').glob('*'));assert len(figs)==8
    write(OUT/'checks/artifact_contract.json',{'passed':True,'utc':utc,'required_files':required,'evaluator_files':2850,'new_reference_files':300,'figure_files':8,'scientific_protocol':str(ROOT/'docs/STAGE6B_FORMAL_VALIDATION_PROTOCOL.md'),'machine_protocol':str(ROOT/'config/stage6b_jb_avg_protocol.json')})
    write(OUT/'checks/figure_checks.json',{'visual_review':'passed','utc':utc,'review':'All four PNGs inspected. Request accuracy includes all-workload paired/unsupported coverage. Judgment chart retains unknown. Capacity chart retains unknown bounds and censoring. Operating chart retains abstentions and unsafe markers; colorbar placed outside data and attainment displayed to three decimals. Matching SVGs exported from the same figures.','files':{p.name:sha(p) for p in figs}})
    q.update(artifact_contract_passed=True,visual_review_passed=True);write(OUT/'checks/quality_checks.json',q)
    completion.update(status='complete',visual_review_passed=True,artifact_contract_passed=True,utc=utc,git_delivery='Final commit and remote verification recorded in task response; commit cannot contain its own hash.');write(OUT/'checks/reporting_completion.json',completion)
    manifest=read(OUT/'provenance/final_runner_manifest.json');manifest.update(utc=utc,files={str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in sorted((OUT/'code').glob('*.py'))});assert sha(OUT/'code/run.py')==manifest['frozen_execution_runner_sha256'];write(OUT/'provenance/final_runner_manifest.json',manifest)
    runtime=read(OUT/'runtime/runtime_summary.json');cost=read(OUT/'runtime/planning_cost.json');stop=read(OUT/'checks/stop_summary.json');ratio=runtime['matched_ratio'];ops=csvread(OUT/'decisions/operating_points.csv')
    lines=['','## Audited execution cost and concrete unsafe recommendations','',f"Matched R/E wall-time ratio over {ratio['count']} qualified complete pairs: median {ratio['median']:.6g}, P95 {ratio['P95']:.6g}, range {ratio['min']:.6g}–{ratio['max']:.6g}. Every workload has timing evidence for all five candidates. These are simulator-call cost ratios, not GPU serving speedups. R includes initialization/extraction and dataclass materialization; E starts from prepared objects. Historical R timing is excluded. Five new E unsupported points are excluded from the matched full-drain ratio, not reported as fast successful predictions.",'',f"Actual campaign wall time: {cost['campaign_elapsed_s']:.3f}s. Actual new R attempts: {cost['actual_R_attempt_wall_s_including_failures']:.3f}s total. E benchmark calls: {cost['actual_E_benchmark_wall_s']:.3f}s total; one primary E call per input: {cost['one_planning_execution_s']:.3f}s. Actual cached-reference processing: {cost['actual_cache_processing_s']:.3f}s; all E/R classification: {cost['actual_classifier_s']:.3f}s. The classifier time overlaps the cache-processing aggregate and must not be added twice. See `runtime/planning_cost.json` for preparation, serialization, profile loading, postprocessing and NA components. Exact repeat-free end-to-end planning cost and historical rebuild cost remain unavailable; no extrapolation is used. Peak memory is the persistent process lifetime high-water mark, not isolated model allocation.",'','| Grid | Workload | SLA | E candidate | Recommended intensity L | R J / K / N | R attainment | Safe usable loss |','|---|---|---|---:|---:|---|---:|---:|']
    for r in ops:
        if r['safe_R']=='False':lines.append(f"| {r['grid_version']} | {r['workload']} | {r['SLA']} | {r['candidate']} | {r['L']} | {r['J_R']} / {r['K']} / {r['N']} | {float(r['A_R']):.9f} | {r['safe_usable_loss']} |")
    lines+=['', 'All ten workloads stopped because each exhausted its six-intensity quota. Remaining eligible transitions are retained, without extra execution. No timeout, technical failure, retry, cache alias conflict or protocol deviation occurred. G0 and its original recommendations remain unchanged.','',f"Independent audit passed {q['independent_check_count']} checks, including per-point classification and provenance, endpoint formulas, successful repeat equality, exact capacity bounds, E-only recommendation, loss, best sets, deterministic refinement replay and dependency hashes. The 41 targeted tests passed. All required files and four PNG/SVG figure pairs are present; visual review passed.",'','Screen disposition: 59 failed cells and one not-assessable cell (h103/S4, due to unidentified sampled capacities). No cell passed; the prerequisites for interpretation A are therefore absent. The B/C conclusions are conditional on the observed failure dimensions, while D applies to the unidentified capacity/ranking evidence.','']
    path=OUT/'reports/FINAL_EVIDENCE_REPORT.md';body=path.read_text(encoding='utf-8').split('\n## Audited execution cost and concrete unsafe recommendations')[0];path.write_text(body+'\n'.join(lines),encoding='utf-8')
    files=[p for p in sorted(OUT.rglob('*')) if p.is_file() and p.name!='artifact_manifest.json' and '__pycache__' not in p.parts and 'matplotlib_cache' not in p.parts and p.suffix!='.tmp']
    write(OUT/'provenance/artifact_manifest.json',{'utc':utc,'algorithm':'sha256','exclusions':['this self-referential manifest','transient __pycache__, matplotlib_cache and .tmp files'],'files':{str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in files},'protocol_files':{str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in [ROOT/'docs/STAGE6B_FORMAL_VALIDATION_PROTOCOL.md',ROOT/'config/stage6b_jb_avg_protocol.json']}})
    print('SEALED',len(files),'files;',q['independent_check_count'],'audit checks')

if __name__=='__main__':main()
